window.WPX_INDEX = [
  {"title": "Labor Advocacy Playbook", "group": "Playbook", "url": "playbook.html", "text": "A six-step advocacy process, position guidance, and six institutional scenarios on course caps, workload, curriculum policy, and labor conditions."},
  {"title": "Position A: Contingent, non-tenure-track, or adjunct", "group": "Playbook · Positions", "url": "playbook.html#positions", "text": "Higher risk: protect yourself first. Course leads, long-term adjuncts, visiting instructors, and non-tenure-track lecturers. Formal governance power is limited. Proximity to students and to the effects of policy gives this position credibility. Build a coalition before acting. Document everything. Seek tenured allies before raising an issue in public. Consider anonymous or collective action."},
  {"title": "Position B: Tenure-track or early-career WPA", "group": "Playbook · Positions", "url": "playbook.html#positions", "text": "Moderate risk: act strategically. Assistant professors, early-career WPAs, and faculty in a first administrative role. Pre-tenure vulnerability exists on some issues. The role also carries formal authority and disciplinary expertise. You have formal standing to raise disciplinary issues. Cite professional standards to move the argument away from personal preference. Build faculty allies. Document administrative work as scholarship."},
  {"title": "Position C: Tenured or experienced WPA", "group": "Playbook · Positions", "url": "playbook.html#positions", "text": "Lower risk: act with full authority. Associate and full professors, established program directors, and WPAs with long service at one institution. This position carries the strongest formal protection and institutional credibility, and with them a responsibility to advocate for others. Lead coalition-building. Bring issues to governance formally. Use the position to protect contingent colleagues. Draw on a national profile where one exists."},
  {"title": "Step 1: Situational Self-Assessment", "group": "Playbook · Six steps", "url": "playbook.html#step-1", "text": "Assess position, power, and risk before acting. Advocacy begins with an honest reading of institutional context. The purpose is not delay. The purpose is action proportionate to your position and risk tolerance, aimed at the place where change is possible. What is your job security: tenure, a long-term contract, a year-to-year appointment, or adjunct status? How long have you been at this institution, and how do the relevant decision-makers regard your work? What is the worst consequence of raising this issue, and is it one you are prepared to accept? What has been tried before on this issue, and what happened? Which formal governance structures exist: a curriculum committee, a faculty senate, collective bargaining? What are the institution's stated priorities this year, and how does your issue fit within them? Write a private memo laying out your position, power, and goals. It clarifies your thinking and records your intent. Review your contract or the faculty handbook for relevant policies before raising the issue formally. Ask two or three senior colleagues who have handled similar issues for informal advice. Map the decision structure: who holds authority over this issue, and where does the formal authority sit? Read the political moment. Accreditation cycles, new administrators, program reviews, and budget conversations create openings. Identify a tenured ally willing to raise the issue with you or on your behalf, with full credit to you. Consider anonymous or collective data collection before attaching your name in public. Know your union contract or collective bargaining agreement, if one exists. It often provides formal channels and protections."},
  {"title": "Step 2: Identify and Connect", "group": "Playbook · Six steps", "url": "playbook.html#step-2", "text": "Map who is affected and build a coalition. Advocacy on structural issues such as class size and workload rarely succeeds when one person acts alone. This step maps who is affected and builds the coalition needed for change. Coalition-building differs from sharing complaints. The aim is to find people who face the same problem, who are willing to work toward a solution, and who help you reach decision-makers. Who else is directly affected: faculty, students, staff, coordinators, writing center directors? Which spaces already exist for raising the issue: department meetings, program committees, faculty learning communities? Are there administrative allies, such as a dean of students, institutional research staff, or a new administrator? Which external pressure points exist: accrediting bodies, state systems, professional organizations? Hold informal conversations before organizing anything formal. Listen more than you speak at this stage. Identify a core group of three to five people across roles and ranks who are motivated and well placed. Map governance: which committees, bodies, or processes have jurisdiction over the issue? Look for moments with built-in urgency, such as program reviews, curricular revisions, and accreditation self-studies. Find out whether your institution has an ombudsperson, a faculty senate, or a union with jurisdiction. Do not share private conversations without explicit permission. Do not read sympathy as willingness to act in public. Ask people directly what they are willing to do. Do not organize by email before you are ready to go formal. Email creates a record."},
  {"title": "Step 3: Gather Local Data", "group": "Playbook · Six steps", "url": "playbook.html#step-3", "text": "Build a fuller account with numbers and testimony. Administrative decisions often rest on incomplete data. Your task is a fuller account: the metrics administrators already track (enrollment, student credit hours, DFW rates, retention) together with a disciplinary reading of what those numbers mean. Data feminism matters here. Ask what the data shows, who produced it, what it was designed to measure, and what it systematically leaves out (D'Ignazio and Klein, 2020). Institutional research or institutional effectiveness: class size distributions, DFW rates by section, enrollment by course type and modality. Registrar: historical enrollment, section caps, and waitlists. Waitlists document demand. Faculty surveys: workload, time spent per student per week, capacity for feedback. Student surveys: perceived quality of feedback, writing center access, connection to the instructor. National data: the national course cap dataset in the Data Guide , the CCCC Principles, and the TYCA workload white paper. Before presenting data, state its limits: what it does not measure, and why. Ask whether the data overrepresents some groups, such as full-time faculty over adjuncts or residential students over commuters. Pair numbers with accounts from faculty and students, with explicit permission from each person. Credit the people whose labor produced the data, and ask whether they are in the room when it is presented."},
  {"title": "Step 4: Compare to National Standards", "group": "Playbook · Six steps", "url": "playbook.html#step-4", "text": "Ground the case in the field's professional standards. A local complaint becomes a disciplinary argument when it rests on the field's published standards. Statements from CCCC, CWPA, TYCA, and MLA record professional consensus, and citing them moves the argument away from individual preference. Find the statement closest to your issue, quote it accurately, and set your local data beside it. CCCC, Principles for the Postsecondary Teaching of Writing (revised 2023): no more than 20 students per writing class, 15 preferred, and no more than 60 writing students per instructor per term. National course cap dataset: among 417 institutions reporting a first-year composition cap, the median is 22. The two-year college median is 25. About 37 percent report a cap of 20 or lower. CWPA, Evaluating the Intellectual Work of Writing Administration (1998): writing program administration is scholarship and merits evaluation as scholarship in tenure and promotion review. Quote the standard exactly and bring a printed copy. Precision matters with administrators. Set your data beside it: \"Our cap of 27 sits 7 students above the CCCC maximum of 20 and 2 above the national two-year college median of 25.\" Frame the issue as professional ethics: \"This is the standard the field has set for effective instruction. It is not my preference.\" If you meet resistance, return to the data: \"Among 417 institutions reporting a first-year composition cap, the median is 22. Ours is 27.\" Present the gap as a student success issue. Larger sections leave less time for response to each student's writing, and the CCCC Principles tie class size to the conditions for effective instruction. The 20 and 60 figures are professional norms grounded in workload analysis. Present them as the field's standard, and do not present them as an experimentally established threshold. Field Commitments explains the distinction."},
  {"title": "Step 5: Plan a Sharing Event", "group": "Playbook · Six steps", "url": "playbook.html#step-5", "text": "Move from private knowledge to shared understanding. With data, national context, and a coalition in place, you need an occasion for collective interpretation. A formal presentation is one option. A department retreat activity, a program committee discussion, and a faculty learning community meeting also serve. The strategic question is whether to include administrative leadership from the start or to build consensus first. Which format fits the audience: a data presentation, a facilitated discussion, a workshop, a written report? Who belongs in the room: faculty first, or chairs and deans from the start? What outcome do you want: shared understanding, a formal resolution, a committee recommendation? Which follow-up structure sustains momentum after the event? To build internal consensus first: a faculty workshop using this Playbook, anonymized survey results returned to participants, or a program retreat with a data presentation. To make the case to administration: a one-page data brief for the chair, a program review addendum, or a section of the accreditation self-study. To create a shared record: a program assessment report, a faculty senate white paper, or a joint letter to the dean signed by multiple faculty. To raise urgency: a direct conversation with the chair anchored in the CCCC standard, or a formal request to present data to the dean. Administrators often do not read long documents. Prepare one page: the current situation, the national standard, the gap, and one specific, bounded request. Pair the page with a longer evidence document for readers who want the full case."},
  {"title": "Step 6: Move into Governance or Beyond", "group": "Playbook · Six steps", "url": "playbook.html#step-6", "text": "Use official channels first, and know the alternatives. Where momentum exists, move through official channels. Bring a formal proposal to the curriculum committee, the faculty senate, or the relevant administrative body, framed with disciplinary authority and local data. Where official channels are blocked, other routes remain. The Trojan Horse approach places your request inside an initiative the administration already values, such as accreditation preparation, student success, or strategic planning. The data stays the same and the frame changes. The decision-maker is persuadable: prepare a formal proposal with data and go through official channels. A governance body has authority: bring the issue to the curriculum committee, the faculty senate, or the relevant body. Official channels are blocked: consider the options below. Trojan Horse: place the request inside an initiative the administration already values, such as accreditation preparation, a retention initiative, DEI planning, or a strategic planning cycle. Faculty senate or governance: bring a resolution or a white paper. A non-binding resolution still creates a formal record and signals a collective faculty position. Collective bargaining or union: where a union exists, contract negotiation and grievance processes provide formal recourse. Consult your union representative first. Accreditor: regional accreditors such as SACSCOC and HLC review evidence of student learning and success. Frame your data in accreditation terms. Professional organizations: TYCA, CWPA, MLA, and AAUP publish standards, and some offer consultation or statements of concern. Confirm what each currently offers. The status of CCCC changed in July 2026, and its statements remain available through the CCCC-L repository . Public or press: a last resort, appropriate only for severe and well-documented violations."},
  {"title": "Course Caps and Workload After State Developmental Education Reforms", "group": "Playbook · Scenarios", "url": "playbook.html#scenario-caps-workload", "text": "Community college · Continuing-contract faculty. Course caps and workload. Moderate risk. A continuing-contract faculty member at a large open-access community college seeks to reduce first-year composition caps from 27 to 22 after the state eliminated non-degree-credit developmental writing. Under the new model all students, including those previously placed in developmental sections, enroll in standard first-year composition. The DFW rate has risen to 33 percent. Begin with data (Step 3). Work with institutional research to disaggregate DFW rates by placement pathway and by cap size, and test whether the increase tracks the removal of developmental support. Cite the TYCA workload white paper and the CCCC Principles as authority. Present the cap reduction as a student success measure tied to the institution's retention goals, and bring it to the curriculum committee."},
  {"title": "Preserving Anti-Racist Pedagogy Under \"Divisive Concepts\" Legislation", "group": "Playbook · Scenarios", "url": "playbook.html#scenario-divisive-concepts", "text": "Regional university · Tenure-track WPA. Curriculum under legislative restriction. Higher risk. A fifth-year tenure-track WPA works at a state institution under enacted \"divisive concepts\" legislation. The composition committee developed anti-racist approaches over three years, and the new law threatens to constrain syllabi and discussion. The dean has requested a \"compliance review\" without guidance on what compliance means. Seek legal clarity first: establish what the legislation prohibits, as distinct from what administrators assume it prohibits. Consult NCTE's intellectual freedom resources and the NCTE Position Statement on Supporting Teachers and Students in Discussing Complex Topics (2024). Build a faculty coalition before responding to the dean. Describe the pedagogy in terms of rhetorical competence and intellectual inquiry. Document everything in writing."},
  {"title": "Resisting an Under-Resourced Early College Initiative", "group": "Playbook · Scenarios", "url": "playbook.html#scenario-early-college", "text": "Comprehensive university · Tenured WPA. Early college on a compressed timeline. Lower risk. In late March a dean asks a tenured WPA to launch first-year writing in a new Early College program beginning in July. The WPA has concerns about instructor qualification, class size, curricular integrity, and student readiness. The dean is under pressure from the board to launch quickly. From a position of relative safety, answer \"not yet\" in place of \"no.\" Anchor the response in the Joint Position Statement on Dual Enrollment in Composition (2019) and the Framework for Success in Postsecondary Writing (2011). Propose conditional agreement: qualified instructors, appropriate caps, a curriculum alignment process, and an adequate timeline. Put your concerns to the dean in writing. If the program proceeds without those conditions, the record protects you and shows good-faith effort."},
  {"title": "Online Section Caps Higher Than Face-to-Face Caps", "group": "Playbook · Scenarios", "url": "playbook.html#scenario-online-parity", "text": "Community college · Adjunct instructor. Online section parity. Higher risk. An adjunct instructor discovers online first-year composition sections capped at 35 while face-to-face sections are capped at 27. Online instructors receive no differential pay and no reduced load, despite higher caps and different labor demands. No formal policy documents the difference. Collect data anonymously at first and survey other online instructors informally. Bring the data to a tenured ally who is willing to raise it through faculty governance. Cite the CCCC statement on online writing instruction (2013), which sets a cap of 20 for online writing courses with 15 preferred, and the TYCA workload white paper. Frame the issue as student equity: an instructor with 35 online students has less time for each student's writing than an instructor with 27 students in a classroom."},
  {"title": "WPA Work Classified as Service Rather Than Scholarship", "group": "Playbook · Scenarios", "url": "playbook.html#scenario-wpa-scholarship", "text": "Research university · Assistant professor. Administrative work in tenure review. Moderate risk. A third-year tenure-track WPA learns through informal feedback of a problem in the tenure review: directing the first-year composition program is counting as service, despite three peer-reviewed articles about the program and national conference presentations. The pre-tenure review is six months away. Act before the pre-tenure review. Bring CWPA's Evaluating the Intellectual Work of Writing Administration (1998) and the CCCC guidelines on scholarship in rhetoric, writing, and composition (2018) to a meeting with your chair. Propose explicit language for the file: \"program development scholarship\" in place of \"service.\" If the chair does not respond, take the same documents to the dean."},
  {"title": "75 Percent Adjunct-Taught Sections and Declining Program Coherence", "group": "Playbook · Scenarios", "url": "playbook.html#scenario-adjunct-ratio", "text": "Liberal arts college · Tenured WPA. Rising adjunct ratio. Lower risk. Over five years the share of sections taught by adjunct faculty has grown from 40 to 75 percent through budget pressure and unreplaced retirements. The tenured WPA documents growing inconsistency in course design, falling student satisfaction scores, and rising DFW rates. The dean attributes the DFW increase to \"student preparedness.\" You have the data and the position for a formal case. Cite the CCCC Statement on Working Conditions for Non-Tenure-Track Writing Faculty (2016), the TYCA workload white paper, and the CCCC statement on faculty hiring (2016). Present disaggregated data: DFW by instructor type, participation in faculty development by instructor type, and student satisfaction by section. Propose a specific intervention with costs. Bring it to the curriculum committee and the faculty senate at the same time."},
  {"title": "CCCC: Principles for the Postsecondary Teaching of Writing", "group": "Position statements", "url": "playbook.html#statements", "text": "The field's standard for class size (20 maximum, 15 preferred, 60 students per instructor per term) and for working conditions. Revised 2023. The first statement to cite in workload and cap discussions."},
  {"title": "CWPA: Evaluating the Intellectual Work of Writing Administration", "group": "Position statements", "url": "playbook.html#statements", "text": "Establishes writing program administration as scholarship for tenure and promotion review. Essential for pre-tenure WPAs arguing for appropriate evaluation of administrative work."},
  {"title": "CCCC: Statement on Working Conditions for Non-Tenure-Track Writing Faculty", "group": "Position statements", "url": "playbook.html#statements", "text": "Addresses contract transparency, equitable pay, professional development, and workload for contingent faculty at every institution type."},
  {"title": "TYCA: White Paper on Two-Year College English Faculty Workload", "group": "Position statements", "url": "playbook.html#statements", "text": "Reports a national survey of 1,062 two-year college English faculty on class size, teaching load, and labor conditions at open-access institutions."},
  {"title": "CCCC: Scholarship in Rhetoric, Writing, and Composition: Guidelines for Faculty, Deans, and Chairs", "group": "Position statements", "url": "playbook.html#statements", "text": "Guidelines for evaluating writing studies scholarship in tenure and promotion review, across institution types and ranks."},
  {"title": "Joint statement: Joint Position Statement on Dual Enrollment in Composition", "group": "Position statements", "url": "playbook.html#statements", "text": "Sets requirements for dual enrollment and early college programs: instructor preparation, curriculum alignment, and an adequate timeline."},
  {"title": "CCCC: Statement of Best Practices in Faculty Hiring", "group": "Position statements", "url": "playbook.html#statements", "text": "Standards for ethical hiring in rhetoric and composition. Relevant to arguments for tenure-track lines, conversion of adjunct positions, and transparent hiring."},
  {"title": "CWPA: All CWPA Position Statements", "group": "Position statements", "url": "playbook.html#statements", "text": "The full list, including outcomes, plagiarism, and workplace bullying. Consult it when the statements above do not address your issue."},
  {"title": "Data-Driven Advocacy Guide", "group": "Data Guide", "url": "data.html", "text": "Heuristics, national course cap benchmarks, a comparison tool, and a five-step guide to DFW conversations."},
  {"title": "Heuristic 1: Planning Your Advocacy", "group": "Data Guide", "url": "data.html#heuristic-1", "text": "What is happening? What is the exigence for this advocacy, and why now? What is your goal ? Which genre does your audience expect: a report, a dashboard, a one-page brief, a presentation? Who is your audience , and which data is legible and credible to them? Where did this data come from? Which biases and limitations should you acknowledge? Who is available to help with data collection and analysis : institutional research, the registrar, faculty governance? Which scholarship and national standards anchor your case? Are you making a comparison ? Which benchmark is appropriate: national, sector, or peer institution? What are the limitations of your data, and how will you name them? Which terms are legible to your audience: enrollment, student credit hours, retention rate, DFW rate? What is your circulation plan ? Who sees this, when, and through which channel?"},
  {"title": "Heuristic 2: Class Size Case Study", "group": "Data Guide", "url": "data.html#heuristic-2", "text": "For campus leaders: a dashboard showing average class size by department, overlaid with cost and student credit hour data. Present caps as a factor in retention as well as a labor issue. For faculty governance: class size distributions by course type and modality, with student learning outcomes beside cap size. Show the learning rationale. For public advocacy: a comparison of class size before and after a change, set beside retention rates or student satisfaction scores. Use the national distribution below. Equity check: do low-enrollment sections such as independent studies, honors sections, and internships distort your averages? Disaggregate by section type before computing means. Transparency rule: every visualization states its data source, its collection date, and its known limitations. Framing principle: present class size as a condition of student success, and cite the CCCC standard as disciplinary authority in place of personal preference."},
  {"title": "Data Feminism Framework", "group": "Data Guide", "url": "data.html#df", "text": "Data is never neutral. Who collected this data? For which purposes, and at whose expense? Whose goals are foregrounded: retention metrics, cost reduction, student learning? Who benefits from the current framing of this data, and who does not? What is not counted? Which working conditions, student needs, and structural factors are invisible in the metric? Who is harmed by the dominant interpretation of this data? Whose labor produced this data, and are they credited? Examine Power. Data analysis and presentation are not neutral acts. Ask who holds the power to collect, interpret, and act on data, and who does not. Institutional research offices, provosts, and accreditors do not collect the data WPAs need. Rethink Binaries and Hierarchies. Administrative data systems flatten complexity: pass or fail, enrolled or not enrolled, retained or not retained. Advocacy work should surface the variation within those categories, especially by race, income, first-generation status, and modality. Elevate Emotion and Embodiment. Pair quantitative data with qualitative accounts, with explicit permission. A statistic about DFW rates is abstract. A faculty member's account of week 10 in a 30-person section is concrete. Question the Default. The default in most institutional data is the full-time, traditional-age, residential student. Check whether your data is being read through this lens, and name it when it is. Consider Context. A 25 percent DFW rate at an open-access community college serving many working adults differs from a 25 percent rate at a selective residential university. Context is the analysis, not a caveat attached to it."},
  {"title": "National Course Cap Benchmarks", "group": "Data Guide", "url": "data.html#benchmarks", "text": "National median first-year composition cap 22. Two-year college median 25. Most common cap 25. About 37 percent of 417 institutions report a cap of 20 or lower. Basic writing, 102, multilingual, ELL, and online section caps. Class size distribution."},
  {"title": "Compare Your Program", "group": "Data Guide", "url": "data.html#compare", "text": "Enter your course caps and sections per instructor to compare with the CCCC maximum of 20, the 60-student load, and the national median. Replaces the Excel workbook dashboard."},
  {"title": "DFW Step 1: Slow Down and Contextualize Nationally", "group": "Data Guide · DFW guide", "url": "data.html#dfw-1", "text": "Ask first for the range of DFW rates in composition at institutions of your type. A 22 percent rate at an open-access community college differs from a 22 percent rate at a selective four-year institution. Your first move is a request for time to gather context. It is not a defense, a promise of fixes, or acceptance of the premise of a \"high\" rate."},
  {"title": "DFW Step 2: Assess Your Student Support Infrastructure", "group": "Data Guide · DFW guide", "url": "data.html#dfw-2", "text": "Before attributing DFW rates to curriculum or instruction, ask what the institution provides. Which general academic support is available, and how do students reach it? Which reading and literacy support exists? Is the writing center adequately staffed, and is its outreach proactive or reactive? Is library and research instruction integrated into courses? Which support exists for multilingual students? Does the institution connect students to support, or wait for self-referral?"},
  {"title": "DFW Step 3: Disaggregate Your DFW Data", "group": "Data Guide · DFW guide", "url": "data.html#dfw-3", "text": "A single DFW rate hides variation. Request disaggregated data. See Derek Mueller's \"Silhouette of DFWI\" for approaches to visualization. By course type: 101, 102, developmental, co-requisite By modality: face-to-face, online, hybrid By student population: first-generation, Pell-eligible, multilingual By section cap: 20 or lower, 21 to 25, 26 or higher By instructor appointment: tenure-line, full-time lecturer, adjunct By schedule and format: early sections, accelerated sessions"},
  {"title": "DFW Step 4: Gather Faculty and Student Perspectives", "group": "Data Guide · DFW guide", "url": "data.html#dfw-4", "text": "Numbers alone do not explain what is happening. Gather qualitative data. Faculty survey: at the end of the term, ask instructors to explain anonymously why each student with a D, F, or W received the grade, and which resources were available for referral. Faculty focus groups: which patterns do instructors see? Which support are they able to provide under current workloads? Student survey: ask students who received DFW grades about barriers, about what would have helped, and about what the institution did not provide."},
  {"title": "DFW Step 5: Connect DFW to Faculty Working Conditions", "group": "Data Guide · DFW guide", "url": "data.html#dfw-5", "text": "Administrative conversations about DFW rates seldom include working conditions. Put the following questions to your own data before the meeting. How many writing students does each instructor teach per term, and how does the number compare with the CCCC maximum of 60? How many instructors teach at more than one campus or institution, and how much time does each appointment leave for office hours and early intervention? Does the DFW rate in your own data differ by section size or by instructor appointment type?"},
  {"title": "Crosswalk Reference", "group": "Crosswalk", "url": "crosswalk_resource.html", "text": "A translation table mapping administrative language to writing studies concepts, with adaptable language and sources for each entry."},
  {"title": "Student Success → Writing as a high-impact practice", "group": "Crosswalk · Student Success", "url": "crosswalk_resource.html#entry-1", "text": "Student Success Student Retention Graduation Rate Student Satisfaction. Metrics of student progression, completion, and academic achievement. AAC&U lists writing-intensive courses among its high-impact practices, and George Kuh's 2008 report for AAC&U associates those practices with student engagement and persistence. Writing courses belong to the institution's student success infrastructure. They are not curricular overhead."},
  {"title": "Student Success → Metacognition and transfer of learning", "group": "Crosswalk · Student Success", "url": "crosswalk_resource.html#entry-2", "text": "Student Success Student Retention Graduation Rate Student Satisfaction. Metrics of student progression, completion, and academic achievement. When students reflect on their writing processes and apply what they learn across contexts, they build the transferable knowledge general education is designed to produce. Transfer is not automatic. A curriculum has to teach for it."},
  {"title": "Student Success → Ongoing, developmental writing growth", "group": "Crosswalk · Student Success", "url": "crosswalk_resource.html#entry-3", "text": "Student Success Student Retention Graduation Rate Student Satisfaction. Metrics of student progression, completion, and academic achievement. Writing development is cumulative. One required course is a threshold and not a destination. Writing distributed across the curriculum gives students the sustained practice through which ability changes."},
  {"title": "Foundational Literacies → Rhetorical competence, genre awareness, and critical thinking through writing", "group": "Crosswalk · Student Success", "url": "crosswalk_resource.html#entry-4", "text": "Foundational Literacies. General education. Functional reading, writing, and communication skills. The administrative term \"foundational literacies\" corresponds to rhetorical competence in writing studies: the ability to read context, purpose, and audience and to communicate accordingly. The concept is more specific and more teachable than \"communication skills.\""},
  {"title": "Workforce Readiness → Rhetorical competence and rhetorical agility", "group": "Crosswalk · Workforce Readiness", "url": "crosswalk_resource.html#entry-5", "text": "Workforce Readiness Enhance Quality Expand Reach and Impact Competency-Based Education. Equip students with the skills employers demand. Enhance institutional reputation. Workforce readiness in communication means rhetorical agility: adapting writing and speaking across audiences, disciplines, and professional contexts. Writing courses develop this capacity when they are well designed and adequately staffed."},
  {"title": "Workforce Readiness → Multimodal communication", "group": "Crosswalk · Workforce Readiness", "url": "crosswalk_resource.html#entry-6", "text": "Workforce Readiness Enhance Quality Expand Reach and Impact Competency-Based Education. Equip students with the skills employers demand. Enhance institutional reputation. Workplace communication is increasingly multimodal. Programs limited to print-based writing leave students underprepared for the visual, digital, and oral composing professional roles now require."},
  {"title": "Workforce Readiness → Genre awareness and fluency", "group": "Crosswalk · Workforce Readiness", "url": "crosswalk_resource.html#entry-7", "text": "Workforce Readiness Enhance Quality Expand Reach and Impact Competency-Based Education. Equip students with the skills employers demand. Enhance institutional reputation. Genre fluency, the knowledge of how memos, reports, proposals, and white papers work, is concrete and teachable. It gives a program a specific answer when employers ask for graduates who write well in professional contexts."},
  {"title": "Workforce Readiness → Professional and technical communication", "group": "Crosswalk · Workforce Readiness", "url": "crosswalk_resource.html#entry-8", "text": "Workforce Readiness Enhance Quality Expand Reach and Impact Competency-Based Education. Equip students with the skills employers demand. Enhance institutional reputation. Technical and professional communication is a specialization with its own research base, pedagogy, and ethics. ATTW's standards and the journal Technical Communication Quarterly guide programs in this area."},
  {"title": "Curricular Reform → Writing Across the Curriculum and Writing in the Disciplines", "group": "Crosswalk · Curriculum Reform", "url": "crosswalk_resource.html#entry-9", "text": "Curricular Reform General Education Reform Streamlining Services. Efficiency, modernization, and accreditation standards. Writing Across the Curriculum has organized curricular reform in U.S. higher education since the 1970s. It distributes writing instruction across programs and builds on the expertise of disciplinary faculty. It requires sustained faculty development, and it does not succeed as an unfunded mandate."},
  {"title": "Curricular Reform → Programmatic coherence", "group": "Crosswalk · Curriculum Reform", "url": "crosswalk_resource.html#entry-10", "text": "Curricular Reform General Education Reform Streamlining Services. Efficiency, modernization, and accreditation standards. Coherent writing instruction is sequenced and scaffolded: students build from introductory to advanced work across the degree. Without coordination, writing requirements become checkboxes."},
  {"title": "Curricular Reform → Pedagogical expertise in writing", "group": "Crosswalk · Curriculum Reform", "url": "crosswalk_resource.html#entry-11", "text": "Curricular Reform General Education Reform Streamlining Services. Efficiency, modernization, and accreditation standards. Teaching writing is a specialized practice, distinct from writing well. Faculty development in writing pedagogy is the mechanism through which WAC policy becomes classroom practice. Research on its effects relies mostly on self-report and program evaluation, so state claims about outcomes with care."},
  {"title": "Curricular Reform → Rhetorical ecologies", "group": "Crosswalk · Curriculum Reform", "url": "crosswalk_resource.html#entry-12", "text": "Curricular Reform General Education Reform Streamlining Services. Efficiency, modernization, and accreditation standards. Writing develops within a whole learning environment: assignment design, feedback culture, physical space, and digital tools. Improving writing outcomes requires attention to this environment as well as to course requirements."},
  {"title": "Operational Efficiency → Recursive writing process", "group": "Crosswalk · Technology", "url": "crosswalk_resource.html#entry-13", "text": "Operational Efficiency. Optimizing processes, reducing labor costs, and using technology for perceived productivity gains. Efficiency in writing does not come from shortening revision. It comes from teaching reliable strategies for drafting and revising. Graham and Perin's 2007 meta-analysis of adolescent writing instruction reports its largest effects for explicit strategy instruction."},
  {"title": "Operational Efficiency → Human agency and the \"human in the loop\"", "group": "Crosswalk · Technology", "url": "crosswalk_resource.html#entry-14", "text": "Operational Efficiency. Optimizing processes, reducing labor costs, and using technology for perceived productivity gains. AI tools support writers, and they do not replace the learning writing produces. Keeping people substantively in the loop is the educational rationale for assigning writing."},
  {"title": "Operational Efficiency → AI literacy", "group": "Crosswalk · Technology", "url": "crosswalk_resource.html#entry-15", "text": "Operational Efficiency. Optimizing processes, reducing labor costs, and using technology for perceived productivity gains. AI literacy means students critically evaluate, appropriately use, and ethically engage with generative AI tools. Writing studies has the pedagogical infrastructure to teach it. Research on AI-mediated writing is still too young to show gains in transferable writing ability, so institutional claims should stay modest."},
  {"title": "Operational Efficiency → Labor equity", "group": "Crosswalk · Technology", "url": "crosswalk_resource.html#entry-16", "text": "Operational Efficiency. Optimizing processes, reducing labor costs, and using technology for perceived productivity gains. The quality of writing instruction depends on instructor working conditions. Unsustainable workloads reduce the time available for response to student writing. Efficiency measures which hollow out instruction carry costs of their own."},
  {"title": "Accreditation → Programmatic assessment", "group": "Crosswalk · Assessment", "url": "crosswalk_resource.html#entry-17", "text": "Accreditation Quality Improvement. Meeting external standards. Systematic evaluation. Accreditation-ready writing assessment rests on systematic evidence of student learning over time, gathered through portfolios or locally designed rubrics, and not on course grades alone. CCCC's assessment statement and AAC&U's Written Communication VALUE rubric give reviewers evidence in a form they recognize."},
  {"title": "Accreditation → Learning outcomes", "group": "Crosswalk · Assessment", "url": "crosswalk_resource.html#entry-18", "text": "Accreditation Quality Improvement. Meeting external standards. Systematic evaluation. Writing outcomes should describe what students do with writing, and not only the forms they have practiced. The WPA Outcomes Statement is the field's benchmark for first-year writing, and the VALUE rubric offers one instrument for assessing it."},
  {"title": "Accreditation → Faculty development", "group": "Crosswalk · Assessment", "url": "crosswalk_resource.html#entry-19", "text": "Accreditation Quality Improvement. Meeting external standards. Systematic evaluation. WAC faculty development connects disciplinary expertise with writing pedagogy. It is the mechanism through which WAC policy reaches classrooms, and it depends on chairs, deans, scheduling, and budget as well as on willing faculty."},
  {"title": "Employee Well-Being → Class size", "group": "Crosswalk · Faculty Labor", "url": "crosswalk_resource.html#entry-20", "text": "Employee Well-Being Institutional Reputation. Faculty working conditions and institutional standing. CCCC's Principles set a maximum of 20 students per writing class, with 15 preferred, and no more than 60 writing students per instructor per term. These figures are professional norms grounded in workload analysis. Above them, the time an instructor has for each student's writing shrinks."},
  {"title": "Employee Well-Being → Faculty workload", "group": "Crosswalk · Faculty Labor", "url": "crosswalk_resource.html#entry-21", "text": "Employee Well-Being Institutional Reputation. Faculty working conditions and institutional standing. Writing instruction is labor-intensive in ways specific to the work: reading drafts, responding, and conferencing. The TYCA workload white paper documents this labor at two-year colleges through a national survey of 1,062 faculty."},
  {"title": "Faculty Roles and Responsibilities → WPA intellectual work and administrative scholarship", "group": "Crosswalk · Faculty Labor", "url": "crosswalk_resource.html#entry-22", "text": "Faculty Roles and Responsibilities Promotion and Tenure. Teaching, research, service, and administration. Criteria for evaluation. Writing program administration is intellectual work. It draws on disciplinary expertise and produces knowledge about pedagogy, assessment, and curriculum. CWPA's 1998 statement supports counting this work toward tenure and promotion. Classifying it as service misrepresents it."},
  {"title": "Entrepreneurial Mindset → Writing-to-learn and rhetorical inquiry", "group": "Crosswalk · Engagement", "url": "crosswalk_resource.html#entry-23", "text": "Entrepreneurial Mindset Innovation. Fostering curiosity and initiative, often in engineering and business contexts. The \"entrepreneurial mindset\" of engineering and business programs corresponds to writing-to-learn in writing studies: low-stakes, exploratory writing which builds curiosity and iterative problem-solving. A 2004 meta-analysis of 48 studies found a small positive average effect on achievement, so assignment design and prompts matter."},
  {"title": "Campus Partnerships → Service-learning, public writing, and community engagement", "group": "Crosswalk · Engagement", "url": "crosswalk_resource.html#entry-24", "text": "Campus Partnerships Experiential Learning. Connecting to local communities. Hands-on learning. Service-learning appears on AAC&U's list of high-impact practices, and public writing gives students real audiences. Both make partnership work visible to the community and to reviewers."},
  {"title": "Professionalism → Socialization, hidden curriculum, and discursive norms", "group": "Crosswalk · Engagement", "url": "crosswalk_resource.html#entry-25", "text": "Professionalism Professional Identity Formation. Conduct aligned with institutional and professional norms. Socialization into a field. \"Professionalism\" in professional programs corresponds to socialization into discursive norms, which often operate as a hidden curriculum. Making those norms explicit and teachable is more equitable than assuming them. It also raises the question of whose norms count as professional."},
  {"title": "Imposter Syndrome → Internalized oppression", "group": "Crosswalk · Engagement", "url": "crosswalk_resource.html#entry-26", "text": "Imposter Syndrome. A term for a social and psychological pattern among students. \"Imposter syndrome\" often reflects structural inequities in whose language, knowledge, and ways of knowing count as legitimate. Naming it as internalized oppression moves the site of intervention from the individual to the institution."},
  {"title": "Continuous Quality Improvement → Iteration, temporality, and empirical writing research", "group": "Crosswalk · Engagement", "url": "crosswalk_resource.html#entry-27", "text": "Continuous Quality Improvement Evidence-Based Longitudinal. Constant monitoring and improvement of processes. Data-driven decisions. Continuity over time. The field's version of continuous improvement is recursive process: drafting, feedback, and revision over time. \"Evidence-based\" in writing studies refers to an empirical research base published in journals such as Research in the Teaching of English , WPA: Writing Program Administration , and College Composition and Communication , in addition to institutional metrics."},
  {"title": "Field Commitments", "group": "Field Commitments", "url": "commitments.html", "text": "Kirsti Cole's claims-based map of twelve foundational commitments in writing studies, with critiques, conditions, and the evidence behind each claim."},
  {"title": "Commitment 1: Writing is rhetorical and situated", "group": "Field Commitments", "url": "commitments.html#commitment-1", "text": "Writers make choices in relation to purpose, audience, genre, medium, evidence, occasion, and institutional consequence. Situating writing should not mean teaching accommodation to dominant institutional norms alone. Critical, translingual, antiracist, feminist, disability, and decolonial scholarship asks whose rhetorical norms are treated as normal. Fulkerson (1979) Berlin (1982) Berlin (1988) Pratt (1991)"},
  {"title": "Commitment 2: Writing is a social practice, not merely an individual cognitive skill", "group": "Field Commitments", "url": "commitments.html#commitment-2", "text": "Writing is learned through participation in communities: feedback, reading, collaboration, uptake, and institutional practice. \"Discourse community\" is easily pictured as more coherent, more stable, and more equally accessible than any community is. Trimbur (1994) Bartholomae (1986)"},
  {"title": "Commitment 3: Writing is a mode of learning and inquiry", "group": "Field Commitments", "url": "commitments.html#commitment-3", "text": "Low-stakes and high-stakes writing help students formulate questions, represent ideas, test claims, reflect, synthesize evidence, and revise their understanding. Writing for these purposes belongs across the curriculum. Writing does not automatically produce learning. Its epistemic value depends on assignment design, scaffolding, response, revision, and material conditions. The 48-study meta-analysis by Bangert-Drowns, Hurley, and Wilkinson (2004) found a small positive average effect, not a universal one. Emig (1977) Langer and Applebee (1987) Bangert-Drowns, Hurley, and Wilkinson (2004)"},
  {"title": "Commitment 4: Writing is recursive, developmental, and processual", "group": "Field Commitments", "url": "commitments.html#commitment-4", "text": "Planning, drafting, researching, reading, composing, revising, editing, and reflecting are interdependent and not linear. \"Process\" does not reduce to a uniform sequence. Process pedagogy has been criticized for treating writing as individual and interior and for neglecting genre, history, ideology, institutional constraint, and unequal access to time and feedback. Murray (1972) Perl (1980) Rose (1980) Flower and Hayes (1981) Graham and Perin (2007)"},
  {"title": "Commitment 5: Revision is re-seeing, not merely proofreading", "group": "Field Commitments", "url": "commitments.html#commitment-5", "text": "Revision includes reconsidering questions, purposes, organization, evidence, warrants, audiences, genre choices, and stakes. Not every assignment merits multiple drafts. Mandatory revision without usable feedback, time, choice, or changed evaluative conditions becomes compliance work. Sommers (1982) Anson (2000) Huisman, Saab, van den Broek, and van Driel (2019)"},
  {"title": "Commitment 6: Writing develops through use in consequential contexts", "group": "Field Commitments", "url": "commitments.html#commitment-6", "text": "Students learn genres by using them in meaningful disciplinary, civic, professional, and public situations, not by memorizing templates. Authenticity is not automatic, and simulated genres retain value. Workplace genres should not be imported uncritically, especially where they reproduce exploitative labor norms. Miller (1984) Russell (1997)"},
  {"title": "Commitment 7: Disciplines are ways of knowing, doing, and writing", "group": "Field Commitments", "url": "commitments.html#commitment-7", "text": "The premise of writing in the disciplines holds writing to be constitutive of disciplinary activity. Michael Carter (2007) calls writing a \"metadoing,\" a practice which gives form to disciplinary ways of doing and knowing. The claim should not reify disciplines, which contain competing methods, genres, ideologies, and publics and which change over time. Instruction in disciplinary writing should teach students to analyze and negotiate disciplinary norms, not only to assimilate. Carter (2007) Russell (1997) Bazerman et al. (2005)"},
  {"title": "Commitment 8: Writing development is lifelong and context-dependent", "group": "Field Commitments", "url": "commitments.html#commitment-8", "text": "No single course teaches students to write once and for all. Programs should distribute meaningful writing experiences across curricular pathways. The corrective to the one-course solution should not become an unfunded mandate for all faculty. Institutions must provide curricular time, faculty development, writing support, equitable workload, and sustained infrastructure. Bazerman et al. (2005) Wardle (2009)"},
  {"title": "Commitment 9: Transfer is possible but not automatic", "group": "Field Commitments", "url": "commitments.html#commitment-9", "text": "Students carry forward genre awareness, rhetorical concepts, strategies, habits of reflection, and prior writing knowledge. They must also recognize when and how these resources apply in a new situation. Transfer should not be framed as a student deficit. A new discipline, genre, modality, language practice, or institutional setting often demands new learning. Barnett and Ceci (2002) Reiff and Bawarshi (2011) Yancey, Robertson, and Taczak (2014)"},
  {"title": "Commitment 10: Reading, research, writing, and citation are intertwined literacy practices", "group": "Field Commitments", "url": "commitments.html#commitment-10", "text": "Academic and professional writing entails evaluating sources, tracing conversations, representing the work of others, and making evidence-based claims. Citation is an epistemic and ethical practice as well as a format. Citation regimes also enact exclusion, Eurocentrism, gatekeeping, and uneven access to scholarly publication. Logan (2008) Royster (1996)"},
  {"title": "Commitment 11: Language difference is a resource, not proof of deficiency", "group": "Field Commitments", "url": "commitments.html#commitment-11", "text": "Students bring linguistic, rhetorical, cultural, technological, and literacy resources to college. The commitment requires more than welcoming language. It entails revising the assessment, feedback, placement, curriculum, and professional-language standards which penalize racialized and multilingual writers. The CCCC Principles reject instruction which standardizes and excludes. Anzaldúa (1987) Matsuda (2006) Rosa and Flores (2017) Baker-Bell et al. (2020) CCCC, Students' Right to Their Own Language (1974)"},
  {"title": "Commitment 12: Writing and communication are multimodal and technologically mediated", "group": "Field Commitments", "url": "commitments.html#commitment-12", "text": "Writing takes print, digital, visual, audio, spatial, data-rich, and networked forms. The commitment should not be technologically deterministic, and multimodal work is not inherently engaging or equitable. Students need access, accessibility support, rhetorical purpose, and critical attention to the political economy and data practices of platforms. Hocks (2003) Shipka (2005) Dolmage (2008) Alexander and Rhodes (2014)"},
  {"title": "Writing Methods and Activities", "group": "Field Commitments", "url": "commitments.html#methods", "text": "Low-stakes writing. Freewrites, annotations, question generation, learning logs, and exit reflections rehearse disciplinary language, externalize uncertainty, and generate material before polished performance. They equalize participation and give instructors evidence in real time. The writing must stay low stakes. Once graded for correctness or monitored, it becomes surveillance in place of exploratory inquiry. High-stakes writing. A high-stakes assignment is defensible when it asks students to undertake an intellectually meaningful task. Strong design makes explicit the rhetorical situation, the intellectual task, the evidence practices, the social and disciplinary work the genre does, and the criteria for success. The assignment should be an occasion for learning, and not only an instrument for sorting, certifying, or catching students. Scaffolding. Proposal memos, annotated bibliographies, evidence tables, genre analyses, research questions, outlines, draft workshops, oral explanations, reflective cover letters, and staged submissions make intellectual work visible. Scaffolding should not multiply deadlines into bureaucratic fragmentation. Peer response and collaborative writing. Writers learn by meeting real readers. They develop rhetorical judgment by reading drafts, articulating criteria, and explaining their responses. Peer response is not self-executing. It requires models, shared purposes, criteria, time, accountability, and attention to power. Unguided peer review reproduces hierarchies and rewards normative language practices. Feedback and conferencing. Response belongs within composing, and not only in evaluative comments afterward. Conferences clarify goals, diagnose composing problems, negotiate feedback, and plan revision. Feedback must be selective and usable. Commenting on every surface feature obscures higher-order work. Conferences are labor-intensive. Reflection and metacognition. Cover letters, process memos, portfolio reflections, rhetorical self-analysis, and genre comparisons are foundational to research on transfer. Reflection should not become ritual self-disclosure. It means most when it asks for evidence-based claims about composing choices and about a changing understanding of rhetorical situations."},
  {"title": "Class Size Is a Pedagogical and Labor Condition", "group": "Field Commitments · Conditions", "url": "commitments.html#class-size", "text": "CCCC recommends 15 or fewer students, a maximum of 20, and 60 writing students per instructor per term. The figures are norms grounded in workload analysis. Enrollment, feedback, modality, staffing, and compensation must be treated together."},
  {"title": "Assessment Is Local, Multiple, and Purpose-Driven", "group": "Field Commitments · Conditions", "url": "commitments.html#assessment", "text": "Contextual, transparent, multiple, and equitable assessment. Portfolios, rubrics, error, placement, grading, timed writing, standardized tests."},
  {"title": "Writing Belongs Throughout an Education: WAC, WID, CAC", "group": "Field Commitments · Conditions", "url": "commitments.html#wac", "text": "Writing across the curriculum, writing in the disciplines, communication across the curriculum. Faculty development, writing intensive courses, writing centers, libraries."},
  {"title": "Productive Tensions", "group": "Field Commitments", "url": "commitments.html#tensions", "text": "General writing knowledge and Disciplinary specificity. Individual writer development and Social and institutional conditions. Process and Product. Support and Standardization. Writing for learning and Writing for assessment. Efficiency and Educational quality."},
  {"title": "What Kind of Evidence Each Claim Has", "group": "Field Commitments", "url": "commitments.html#evidence", "text": "Activity, pedagogy, and method registers. Meta-analysis, effect sizes, strategy instruction, feedback, peer response, writing-to-learn. Transfer, genre, class size, and labor rest on qualitative, theoretical, and program evidence."},
  {"title": "About the Exchange", "group": "About", "url": "index.html#about", "text": "Co-directed by Kirsti Cole and Holly Hassel. A searchable, updatable resource for writing program administrators. Origins in a 2025 CCCC working session."},
  {"title": "A Note on CCCC", "group": "About", "url": "index.html#cccc-note", "text": "The de-chartering of CCCC in July 2026, how the Exchange cites CCCC position statements, and the CCCC-L archive of statements."},
  {"title": "Contribute a Scenario or Resource", "group": "About", "url": "index.html#contribute", "text": "Submit a scenario, a data visualization, or a crosswalk entry. Contact the co-directors. Report a broken link. Suggested citation."},
  {"title": "When Words Become Work: Composition Studies Special Issue", "group": "About", "url": "index.html#about", "text": "Special issue of Composition Studies edited by Kirsti Cole and Holly Hassel on turning disciplinary knowledge into institutional action."},
];
